#!/usr/bin/env bun

/**
 * post-build: writes dist/client/single-page.md — the whole wiki as one
 * markdown file, byte-for-byte what fmhy.net serves at /single-page.md.
 *
 * Port of upstream scripts/generate-single-page.js (run by their docs:build):
 * a BOM + autogenerated comment, then each wiki page's raw markdown joined by
 * a blank line. The page list is read out of that script at build time rather
 * than copied here, so a page added upstream lands with no edit on our side.
 *
 * Skips with a warning when no fmhy/edit checkout is present (a local build
 * without `bun scripts/sync-fmhy.ts`); CI always has one.
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

import { FMHY_ROOT } from './wiki/fmhy-root'

const distClient = join(process.cwd(), 'dist', 'client')
const upstreamScript = join(FMHY_ROOT, 'scripts', 'generate-single-page.js')

if (!existsSync(distClient)) {
  console.error('single-page: dist/client not found — run `one build` first')
  process.exit(1)
}

if (!existsSync(upstreamScript)) {
  console.warn(`single-page: ${upstreamScript} not found — single-page.md skipped`)
  process.exit(0)
}

// `const files = [ 'privacy.md', ... ]` in their script
const list = /const files = \[([\s\S]*?)\]/.exec(readFileSync(upstreamScript, 'utf8'))
const files = list ? [...list[1]!.matchAll(/'([^']+\.md)'/g)].map((m) => m[1]!) : []
if (files.length === 0) {
  console.error(`single-page: no page list found in ${upstreamScript}`)
  process.exit(1)
}

const contents = files.map((file) => {
  const path = join(FMHY_ROOT, 'docs', file)
  if (!existsSync(path)) {
    console.warn(`single-page: ${path} not found`)
    return ''
  }
  return readFileSync(path, 'utf8')
})

const body =
  '﻿<!-- This is autogenerated content, do not edit manually. -->\n' +
  contents.join('\n\n')

writeFileSync(join(distClient, 'single-page.md'), body)
console.info(`single-page: single-page.md written (${files.length} pages)`)
